INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l50','state verbs (no -ing)','',NULL,'/steɪt vɜːrbz/','This box contains 48 matches.','这盒子里装有 48 根火柴。','Those papers belong to me.','那些报纸是我的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l50','lose / loose / miss','',NULL,'/luːz luːs mɪs/','Don''t lose your passport.','别把护照弄丢了。','Hurry, or we''ll miss the train.','快点,不然赶不上火车。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l50','expect vs wait for','',NULL,'/ɪkˈspekt/','I''m expecting Jack at six.','我预计杰克六点到。','I won''t wait for him if he''s late.','他迟到我就不等他。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l50','take sb for a ride','',NULL,'/teɪk fɔːr ə raɪd/','He was taken for a ride and lost his money.','他被骗了,还损失了钱。','Don''t let them take you for a ride.','别让他们骗你。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp1','choice','{"stem":"\"This box ___ 48 matches.\"(表状态,用一般现在时:里面装有)","options":["contain","containing","is containing","contains"],"answer_index":3,"stem_cn":"这个盒子里装有 48 根火柴。","explanation_cn":"contain 是状态动词,表示\"里面装有\",用一般现在时,不用进行时。✓ This box contains 48 matches. ✗ is containing:状态动词不用进行时;✗ contain:主语 box 是第三人称单数要加 s;✗ containing:缺少动词。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp1','choice','{"stem":"\"Those papers ___ to me.\"(属于…,表状态不用进行时)","options":["belonging","are belonging","belong","is belonging"],"answer_index":2,"stem_cn":"那些报纸是我的。","explanation_cn":"belong(属于)是状态动词,表状态,不用进行时。✓ Those papers belong to me. ✗ are belonging / is belonging:状态动词不用进行时;✗ belonging:缺少谓语。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp1','choice','{"stem":"\"He ___ a new pair of shoes.\"(需要,表状态)","options":["needs","is needing","need","needing"],"answer_index":0,"stem_cn":"他需要一双新鞋。","explanation_cn":"need(需要)表状态,用一般现在时;主语 He 第三人称单数加 s。✓ He needs a new pair of shoes. ✗ is needing:状态动词不用进行时;✗ need:漏了 s;✗ needing:缺少动词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp1','choice','{"stem":"\"I ___ writing letters.\"(讨厌,表状态不用进行时)","options":["hates","hating","am hating","hate"],"answer_index":3,"stem_cn":"我讨厌写信。","explanation_cn":"hate(讨厌)是状态动词,表状态,不用进行时;主语 I 用原形。✓ I hate writing letters. ✗ am hating:状态动词不用进行时;✗ hates:I 不加 s;✗ hating:缺少动词。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp1','choice','{"stem":"\"I ___ this song very much.\"(喜爱,表状态动词)","options":["love","loves","am loving","loving"],"answer_index":0,"stem_cn":"我非常喜欢这首歌。","explanation_cn":"love(喜爱)是状态动词,表状态,不用进行时;主语 I 用原形。✓ I love this song very much. ✗ am loving:状态动词不用进行时;✗ loves:I 不加 s;✗ loving:缺少动词。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp1','choice','{"stem":"\"This machine ___ of three parts.\"(由…组成,表状态)","options":["consisting","consist","consists","is consisting"],"answer_index":2,"stem_cn":"这台机器由三部分组成。","explanation_cn":"consist of(由…组成)是状态动词,表状态,用一般现在时;主语 machine 加 s。✓ This machine consists of three parts. ✗ is consisting:不用进行时;✗ consist:漏了 s;✗ consisting:缺少动词。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp2','choice','{"stem":"\"Water ___ at 100°C.\"(客观规律,用一般现在时)","options":["is boiling","boil","boiled","boils"],"answer_index":3,"stem_cn":"水在 100 摄氏度沸腾。","explanation_cn":"客观规律、总是如此的事用一般现在时;主语 Water 加 s。✓ Water boils at 100°C. ✗ is boiling:此处不是\"正在沸腾\"而是普遍规律;✗ boil:漏了 s;✗ boiled:不是过去的事。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp2','choice','{"stem":"\"Look! The bus ___.\"(此刻正在发生,用现在进行时)","options":["is coming","come","comes","came"],"answer_index":0,"stem_cn":"看!公交车来了。","explanation_cn":"Look! 提示此刻正在发生,用现在进行时。✓ Look! The bus is coming. ✗ comes:一般现在不表此刻;✗ come:缺助动词;✗ came:不是过去。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp2','choice','{"stem":"\"He usually ___ to work by bus.\"(usually 表习惯,用一般现在时)","options":["going","goes","is going","go"],"answer_index":1,"stem_cn":"他通常坐公交车上班。","explanation_cn":"usually 是习惯标志词,用一般现在时;主语 He 加 s。✓ He usually goes to work by bus. ✗ is going:习惯不用进行时;✗ go:漏了 s;✗ going:缺少动词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp2','choice','{"stem":"\"She always ___ the front seat on the bus.\"(always 表习惯,用一般现在时)","options":["taking","is taking","takes","take"],"answer_index":2,"stem_cn":"她总是坐公交车的前排。","explanation_cn":"always 是习惯标志词,用一般现在时;主语 She 加 s。✓ She always takes the front seat on the bus. ✗ is taking:习惯不用进行时;✗ take:漏了 s;✗ taking:缺少动词。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp3','choice','{"stem":"\"Take care not to ___ your passport.\"(丢失)","options":["lose","miss","loose","losing"],"answer_index":0,"stem_cn":"小心别把护照弄丢了。","explanation_cn":"\"丢失\"用动词 lose /luːz/。✓ Take care not to lose your passport. ✗ loose:是形容词\"松的\";✗ miss:是\"错过、想念\";✗ losing:缺少动词原形(not to + 原形)。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp3','choice','{"stem":"\"Several screws have come ___.\"(松了,形容词''松的'')","options":["lose","loose","missed","loosen"],"answer_index":1,"stem_cn":"有几个螺丝松了。","explanation_cn":"\"松的\"用形容词 loose /luːs/。✓ Several screws have come loose. ✗ lose:动词\"丢失\";✗ missed:\"错过\";✗ loosen:是动词\"使松开\"。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp3','choice','{"stem":"\"Hurry up! You''ll ___ the bus.\"(错过,赶不上)","options":["loose","lose","miss","lost"],"answer_index":2,"stem_cn":"快点!你会赶不上公交车的。","explanation_cn":"\"错过、赶不上\"用 miss。✓ Hurry up! You''ll miss the bus. ✗ lose:\"丢失\";✗ loose:\"松的\";✗ lost:过去式,此处要原形。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp4','choice','{"stem":"\"I am ___ Jack to arrive at six o''clock.\"(预计…会来)","options":["looking","waiting","hoping for","expecting"],"answer_index":3,"stem_cn":"我预计杰克六点钟到。","explanation_cn":"expect 表\"预计…会发生/会来\",可用进行时 be expecting sb to do。✓ I am expecting Jack to arrive at six o''clock. ✗ waiting:等候要用 wait for;✗ hoping for / looking:搭配不对。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp4','choice','{"stem":"\"I shall not ___ him if he is late.\"(等候某人,后面带介词的那个)","options":["expect","wait","wait for","await for"],"answer_index":2,"stem_cn":"如果他迟到,我就不等他了。","explanation_cn":"\"等候某人\"用 wait for(带介词 for)。✓ I shall not wait for him if he is late. ✗ expect:是\"预计会来\"不是\"等\";✗ wait:缺介词 for;✗ await for:await 后不加 for。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp5','choice','{"stem":"\"The conductor told me ___ to get off.\"(疑问词+不定式:在哪儿)","options":["where","because","which","that"],"answer_index":0,"stem_cn":"售票员告诉我在哪儿下车。","explanation_cn":"\"疑问词 + 不定式\"表\"在哪儿做某事\"用 where to do。✓ The conductor told me where to get off. ✗ that / which / because:不能接不定式构成这个名词结构。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp5','choice','{"stem":"\"I didn''t know ___ to do next.\"(疑问词+不定式:什么)","options":["which one","that","what","because"],"answer_index":2,"stem_cn":"我不知道接下来做什么。","explanation_cn":"\"疑问词 + 不定式\"表\"做什么\"用 what to do。✓ I didn''t know what to do next. ✗ that / which one / because:此处要 what + 不定式。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',5,'am2_l50_gp6','choice','{"stem":"\"In that case, I ___ to stay on the bus.\"(宁愿、更喜欢做某事)","options":["suggest","enjoy","mind","prefer"],"answer_index":3,"stem_cn":"那样的话,我宁愿待在车上。","explanation_cn":"\"宁愿、更喜欢做某事\"用 prefer to do。✓ In that case, I prefer to stay on the bus. ✗ enjoy:后接 -ing;✗ mind:介意;✗ suggest:建议。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',6,NULL,'choice','{"stem":"美语里\"地铁\"常说:","options":["metro rail","subway","underground","tube"],"answer_index":1,"explanation_cn":"美语\"地铁\"常说 subway;英式说 underground(口语 tube)。✓ take the subway 坐地铁。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',6,NULL,'choice','{"stem":"美语里\"人行道\"常说:","options":["walk way","pavement","sidewalk","footpath"],"answer_index":2,"explanation_cn":"美语\"人行道\"常说 sidewalk;英式说 pavement。✓ walk on the sidewalk 走人行道。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',6,NULL,'choice','{"stem":"excursion 的意思是:","options":["风景","远足,短途旅行","迷路","车费"],"answer_index":1,"explanation_cn":"excursion = 远足、短途旅行。✓ go on an excursion 去短途旅行。\n顺带记:迷路 = lose one''s way;风景 = view;车费 = fare."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',6,NULL,'choice','{"stem":"conductor 的意思是:","options":["售票员,乘务员","警察","司机","乘客"],"answer_index":0,"explanation_cn":"conductor = (公共汽车)售票员、乘务员。✓ said to the conductor 对售票员说。\n顺带记:司机 = driver;乘客 = passenger;警察 = police officer."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',6,NULL,'choice','{"stem":"view 的意思是:","options":["气味","景色,风景","声音","地图"],"answer_index":1,"explanation_cn":"view = 景色、风景。✓ a good view of the countryside 农村的好风光。\n顺带记:声音 = sound;气味 = smell;地图 = map."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',6,NULL,'choice','{"stem":"ride 的意思是:","options":["散步","飞行","(乘车)旅行,兜风","航行"],"answer_index":2,"explanation_cn":"ride = (乘车、骑马等的)旅行、兜风。✓ taken for a ride 载去兜风(也指被骗)。\n顺带记:散步 = walk;飞行 = flight;航行 = voyage."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',7,NULL,'cloze','{"stem":"第 1 空","context":"Let''s eat here, I said to my wife. I ___1___ to have a drink first, she said. The menu is all in Spanish and I ___2___ a thing on it. ''What ___3___ that word mean?'' I asked. ''I ___4___,'' she answered.","blank_no":1,"options":["prefer","am preferring","prefers","preferring"],"answer_index":0,"explanation_cn":"prefer(更喜欢)是状态动词,表状态,用一般现在时,不用进行时。✓ I prefer to have a drink first.\n✗ am preferring:状态动词不用进行时;✗ prefers:主语 I 不加 s;✗ preferring:缺少动词。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',7,NULL,'cloze','{"stem":"第 2 空","context":"Let''s eat here, I said to my wife. I ___1___ to have a drink first, she said. The menu is all in Spanish and I ___2___ a thing on it. ''What ___3___ that word mean?'' I asked. ''I ___4___,'' she answered.","blank_no":2,"options":["don''t understand","am not understanding","doesn''t understand","not understand"],"answer_index":0,"explanation_cn":"understand(理解)是状态动词,否定用一般现在时 don''t understand,不用进行时。✓ I don''t understand a thing on it.\n✗ am not understanding:状态动词不用进行时;✗ doesn''t understand:主语 I 不用 doesn''t;✗ not understand:缺助动词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',7,NULL,'cloze','{"stem":"第 3 空","context":"Let''s eat here, I said to my wife. I ___1___ to have a drink first, she said. The menu is all in Spanish and I ___2___ a thing on it. ''What ___3___ that word mean?'' I asked. ''I ___4___,'' she answered.","blank_no":3,"options":["does","is","do","did"],"answer_index":0,"explanation_cn":"一般现在时特殊疑问,主语 that word 第三人称单数,用助动词 does + 原形 mean。✓ What does that word mean?\n✗ is:mean 是实义动词要用 do/does;✗ do:第三人称单数用 does;✗ did:不是过去。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',7,NULL,'cloze','{"stem":"第 4 空","context":"Let''s eat here, I said to my wife. I ___1___ to have a drink first, she said. The menu is all in Spanish and I ___2___ a thing on it. ''What ___3___ that word mean?'' I asked. ''I ___4___,'' she answered.","blank_no":4,"options":["don''t know","am not knowing","doesn''t know","not know"],"answer_index":0,"explanation_cn":"know(知道)是状态动词,否定用一般现在时 don''t know,不用进行时。✓ I don''t know.\n✗ am not knowing:状态动词不用进行时;✗ doesn''t know:主语 I 不用 doesn''t;✗ not know:缺助动词。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',8,NULL,'choice','{"stem":"Where did the writer want to go?","options":["The train station","Home","The city center","Woodford Green"],"answer_index":3,"explanation_cn":"课文说 I''m going to Woodford Green,作者想去伍德福德草地。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',8,NULL,'choice','{"stem":"Why didn''t the writer get off at Woodford Green?","options":["He changed his mind","The conductor forgot to tell him and the bus went past it","He fell asleep","The bus never stopped"],"answer_index":1,"explanation_cn":"课文说售票员说 I forgot to put you off,他忘了让作者下车,车就开过了站。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',8,NULL,'choice','{"stem":"What did the writer decide to do at the end?","options":["Stay on the bus as it went back","Take a taxi","Get off and walk","Complain to the driver"],"answer_index":0,"explanation_cn":"课文结尾说 in that case, I prefer to stay on the bus,他宁愿留在车上跟着往回开。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',9,NULL,'choice','{"stem":"你想说\"这些报纸是我的\"(状态动词 belong 表状态,不用进行时):","options":["Those papers belonging to me.","Those papers do belonging to me.","Those papers are belonging to me.","Those papers belong to me."],"answer_index":3,"explanation_cn":"belong(属于)是状态动词,表状态,不用进行时。✓ Those papers belong to me. 场合:说某物属于谁。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',9,NULL,'choice','{"stem":"你想说\"快点!你会赶不上公交车\"(错过、赶不上用 miss):","options":["Hurry up! You''ll loose the bus.","Hurry up! You''ll miss the bus.","Hurry up! You''ll lose the bus.","Hurry up! You''ll missing the bus."],"answer_index":1,"explanation_cn":"\"错过、赶不上\"用 miss(不是 lose,也不是形容词 loose)。✓ Hurry up! You''ll miss the bus. 场合:提醒别人快点,否则赶不上车。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',9,NULL,'choice','{"stem":"你想说\"我告诉你在哪儿下车\"(疑问词+不定式 where to do):","options":["I''ll tell you where to get off.","I''ll tell you where get off.","I''ll tell you where to getting off.","I''ll tell you that where get off."],"answer_index":0,"explanation_cn":"\"疑问词 + 不定式\"可整体跟在动词后面用 where to get off。✓ I''ll tell you where to get off. 场合:告诉别人在哪儿下车。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',10,NULL,'choice','{"stem":"excursion 的意思是:","options":["车费","迷路","远足,短途旅行","风景"],"answer_index":2,"explanation_cn":"excursion = 远足、短途旅行。✓ go on an excursion 去短途旅行。\n顺带记:迷路 = lose one''s way;风景 = view;车费 = fare."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',10,NULL,'choice','{"stem":"view 的意思是:","options":["声音","气味","地图","景色,风景"],"answer_index":3,"explanation_cn":"view = 景色、风景。✓ a good view of the countryside 农村的好风光。\n顺带记:声音 = sound;气味 = smell;地图 = map."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',10,NULL,'choice','{"stem":"\"This box ___ 48 matches.\"(状态动词,用一般现在时)","options":["contains","contain","containing","is containing"],"answer_index":0,"stem_cn":"这个盒子里装有 48 根火柴。","explanation_cn":"contain 是状态动词,表\"里面装有\",用一般现在时,不用进行时;主语 box 加 s。✓ This box contains 48 matches.\n✗ is containing:状态动词不用进行时;✗ contain:漏了 s;✗ containing:缺少动词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',10,NULL,'choice','{"stem":"\"Take care not to ___ your passport.\"(丢失)","options":["loose","lose","lost","miss"],"answer_index":1,"stem_cn":"小心别把护照弄丢了。","explanation_cn":"\"丢失\"用动词 lose /luːz/。✓ Take care not to lose your passport.\n✗ loose:形容词\"松的\";✗ miss:\"错过、想念\";✗ lost:过去式,此处要原形。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',10,NULL,'choice','{"stem":"\"This is as far as we go.\" 这句话的意思是:","options":["我们走得很远。","我们要下车。","我们只到这儿(终点了)。","我们刚出发。"],"answer_index":2,"explanation_cn":"This is as far as we go. as far as = 到…为止,这句意思是\"我们只开到这儿(到终点了)\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',10,NULL,'choice','{"stem":"\"I forgot to put you off.\" 这句话的意思是:","options":["我记得让你下车。","我把你推下去了。","我忘了收你的钱。","我忘了让你下车了。"],"answer_index":3,"explanation_cn":"I forgot to put you off. put sb off = 让某人下车,forgot to do = 忘了做,意思是\"我忘了让你下车了\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',10,NULL,'choice','{"stem":"Why did the writer sit in the front of the bus?","options":["To talk to the driver","To be near the door","To get a good view of the countryside","Because the back was full"],"answer_index":2,"passage":"I love traveling in the country, but I don''t like losing my way. I went on an excursion recently, but my trip took me longer than I expected. ''I''m going to Woodford Green,'' I said to the conductor as I got on the bus, ''but I don''t know where it is.'' ''I''ll tell you where to get off,'' answered the conductor. I sat in the front of the bus to get a good view of the countryside. After some time, the bus stopped. Looking round, I realized with a shock that I was the only passenger left on the bus. ''You''ll have to get off here,'' the conductor said. ''This is as far as we go.'' ''Is this Woodford Green?'' I asked. ''Oh dear,'' said the conductor suddenly. ''I forgot to put you off.'' ''It doesn''t matter,'' I said. ''I''ll get off here.'' ''We''re going back now,'' said the conductor. ''Well, in that case, I prefer to stay on the bus,'' I answered.","explanation_cn":"课文说 I sat in the front of the bus to get a good view of the countryside,他坐前部是为了看风景。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',10,NULL,'choice','{"stem":"Why is the story called ''Taken for a ride''?","options":["He rode the whole route and back, as if taken on a joyride","He got a free ticket","He drove the bus himself","He paid too much"],"answer_index":0,"passage":"I love traveling in the country, but I don''t like losing my way. I went on an excursion recently, but my trip took me longer than I expected. ''I''m going to Woodford Green,'' I said to the conductor as I got on the bus, ''but I don''t know where it is.'' ''I''ll tell you where to get off,'' answered the conductor. I sat in the front of the bus to get a good view of the countryside. After some time, the bus stopped. Looking round, I realized with a shock that I was the only passenger left on the bus. ''You''ll have to get off here,'' the conductor said. ''This is as far as we go.'' ''Is this Woodford Green?'' I asked. ''Oh dear,'' said the conductor suddenly. ''I forgot to put you off.'' ''It doesn''t matter,'' I said. ''I''ll get off here.'' ''We''re going back now,'' said the conductor. ''Well, in that case, I prefer to stay on the bus,'' I answered.","explanation_cn":"售票员忘了让他下车,他坐完全程还要跟着往回开,像被\"载去兜了一圈\",故题为 Taken for a ride。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',10,NULL,'choice','{"stem":"When did the writer realize something was wrong?","options":["When he paid the fare","When he reached Woodford Green","As soon as he got on","When he found he was the only passenger left"],"answer_index":3,"audio":"I love traveling in the country, but I don''t like losing my way. I went on an excursion recently, but my trip took me longer than I expected. ''I''m going to Woodford Green,'' I said to the conductor as I got on the bus, ''but I don''t know where it is.'' ''I''ll tell you where to get off,'' answered the conductor. I sat in the front of the bus to get a good view of the countryside. After some time, the bus stopped. Looking round, I realized with a shock that I was the only passenger left on the bus. ''You''ll have to get off here,'' the conductor said. ''This is as far as we go.'' ''Is this Woodford Green?'' I asked. ''Oh dear,'' said the conductor suddenly. ''I forgot to put you off.'' ''It doesn''t matter,'' I said. ''I''ll get off here.'' ''We''re going back now,'' said the conductor. ''Well, in that case, I prefer to stay on the bus,'' I answered.","explanation_cn":"课文说 Looking round, I realized with a shock that I was the only passenger left,发现只剩自己时才察觉不对。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l50',10,NULL,'choice','{"stem":"What did the conductor say when the writer asked if it was Woodford Green?","options":["''Yes, this is it.''","''Oh dear, I forgot to put you off.''","''We passed it long ago.''","''You''re on the wrong bus.''"],"answer_index":1,"audio":"I love traveling in the country, but I don''t like losing my way. I went on an excursion recently, but my trip took me longer than I expected. ''I''m going to Woodford Green,'' I said to the conductor as I got on the bus, ''but I don''t know where it is.'' ''I''ll tell you where to get off,'' answered the conductor. I sat in the front of the bus to get a good view of the countryside. After some time, the bus stopped. Looking round, I realized with a shock that I was the only passenger left on the bus. ''You''ll have to get off here,'' the conductor said. ''This is as far as we go.'' ''Is this Woodford Green?'' I asked. ''Oh dear,'' said the conductor suddenly. ''I forgot to put you off.'' ''It doesn''t matter,'' I said. ''I''ll get off here.'' ''We''re going back now,'' said the conductor. ''Well, in that case, I prefer to stay on the bus,'' I answered.","explanation_cn":"课文说售票员突然说 Oh dear… I forgot to put you off,承认忘了让他下车。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
